<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useListState} from '../../composables/useListState.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import ResourceForm from '../fields/ResourceForm.vue'
import {options,accountingNames,clone,sortRows} from '../fields/resourceUi.js'
const r=useIrrigation(),route=useRoute(),ui=useListState('network'),sourceId=ref(''),editing=ref(null)
const e=computed(()=>r.state.entities),pipes=computed(()=>e.value.PipeNode??[]),sources=computed(()=>pipes.value.filter(n=>!n.parentNodeId)),zones=computed(()=>e.value.IrrigationZone??[]),selected=computed(()=>zones.value.find(z=>z.zoneId===ui.selectedId)??zones.value[0]),node=computed(()=>pipes.value.find(n=>n.nodeId===selected.value?.sourceNodeId)),fieldName=id=>e.value.Field?.find(f=>f.fieldId===id)?.name??'—'
function rootOf(id){let n=pipes.value.find(n=>n.nodeId===id),seen=new Set;while(n?.parentNodeId&&!seen.has(n.nodeId)){seen.add(n.nodeId);n=pipes.value.find(p=>p.nodeId===n.parentNodeId)}return n?.nodeId}
function select(z){ui.selectedId=z.zoneId;sourceId.value=rootOf(z.sourceNodeId)}
watch(()=>route.query.zoneId,id=>{select(zones.value.find(z=>z.zoneId===id)??selected.value??{});const i=zones.value.findIndex(z=>z.zoneId===id);if(i>=0)ui.page=Math.floor(i/15)+1},{immediate:true})
watch(sources,()=>{if(!sourceId.value)sourceId.value=sources.value[0]?.nodeId},{immediate:true})
const source=computed(()=>pipes.value.find(n=>n.nodeId===sourceId.value)),trunk=computed(()=>{const selectedNode=pipes.value.find(n=>n.nodeId===selected.value?.sourceNodeId);return selectedNode&&rootOf(selectedNode.nodeId)===sourceId.value?selectedNode:pipes.value.find(n=>n.parentNodeId===sourceId.value&&n.kind==='MAIN')??source.value}),branches=computed(()=>zones.value.filter(z=>z.sourceNodeId===trunk.value?.nodeId)),rows=computed(()=>sortRows(zones.value,ui.sort).slice((ui.page-1)*15,ui.page*15))
function editPipe(n){editing.value={title:n?'管段参数':'新增管段',action:'PIPE_SAVE',record:clone(n??{name:'',kind:'BRANCH',parentNodeId:sourceId.value,capacityM3h:null,maxConcurrentZones:1,depthCm:0,intervalCm:0,designFlowM3h:null,status:'ENABLED'}),fields:[{key:'nodeId',label:'管段编号',readonly:true},{key:'name',label:'管段名称',required:true},{key:'kind',label:'节点类型',options:['SOURCE','MAIN','BRANCH'].map(value=>({value,label:{SOURCE:'水源',MAIN:'主管',BRANCH:'支管'}[value]}))},{key:'parentNodeId',label:'父节点',options:options(pipes.value.filter(p=>p.nodeId!==n?.nodeId),'nodeId')},...['capacityM3h','maxConcurrentZones','depthCm','intervalCm','designFlowM3h'].map((key,i)=>({key,label:['供水能力（m³/h）','最多同时运行分区数','实测埋深（cm）','管带间距（cm）','设计流量（m³/h）'][i],type:'number'}))]}}
function editZone(z){editing.value={title:z?'分区参数':'新增分区',action:z?'ZONE_UPDATE':'ZONE_CREATE',record:clone(z??{name:'',fieldId:'',sourceNodeId:trunk.value?.nodeId??sourceId.value,valveDeviceId:'',areaMu:null,designFlowM3h:null,accountingMethod:'MEASURED',meterPointId:'',soilPointIds:[],allocationRule:'',status:'ENABLED'}),fields:[{key:'zoneId',label:'分区编号',readonly:true},{key:'name',label:'分区名称',required:true},{key:'fieldId',label:'所属田块',options:options((e.value.Field??[]).filter(x=>x.status==='ENABLED'),'fieldId')},{key:'sourceNodeId',label:'供水节点',options:options(pipes.value.filter(x=>x.status==='ENABLED'),'nodeId')},{key:'valveDeviceId',label:'控制阀门',options:options((e.value.Device??[]).filter(x=>x.kind==='VALVE'&&x.status==='ENABLED'),'deviceId')},{key:'areaMu',label:'面积（亩）',type:'number'},{key:'designFlowM3h',label:'设计流量（m³/h）',type:'number'},{key:'accountingMethod',label:'计量方式',options:Object.entries(accountingNames).map(([value,label])=>({value,label}))},{key:'meterPointId',label:'独立计量点',options:options((e.value.Point??[]).filter(p=>p.kind==='METER_TOTAL'),'pointId','pointId')},{key:'soilPointIds',label:'土层点集合（按Ctrl多选）',multiple:true,options:options((e.value.Point??[]).filter(p=>p.kind==='SOIL_MOISTURE'),'pointId','pointId')},{key:'allocationRule',label:'分摊依据',type:'textarea'}]}}
const columns=[{key:'index',label:'序号',width:70},{key:'zoneId',label:'分区编号'},{key:'name',label:'分区名称',sortable:true},{key:'fieldId',label:'田块'},{key:'areaMu',label:'面积（亩）',sortable:true},{key:'designFlowM3h',label:'设计流量（m³/h）',sortable:true},{key:'accountingMethod',label:'计量'}]
</script>
<template><div class="page-stack network-screen"><div class="filters network-toolbar"><label class="filter-field">水源<select v-model="sourceId"><option v-for="s in sources" :key="s.nodeId" :value="s.nodeId">{{s.name}}</option></select></label><button class="btn btn-primary" :disabled="!r.can('PIPE_SAVE')" @click="editPipe()">新增管段</button><button class="btn" :disabled="!r.can('ZONE_CREATE')" @click="editZone()">新增分区</button></div><div class="network-top"><section class="panel topology"><h3 class="panel-title">管网拓扑</h3><svg :viewBox="`0 0 610 ${Math.max(180,branches.length*60)}`" role="group" aria-label="可选择的供水管网"><path d="M140 93H205M365 93H390" stroke="#158665" stroke-width="2" fill="none"/><path v-for="(z,i) in branches" :key="z.zoneId" :d="`M365 93 C410 93 375 ${35+i*60} 440 ${35+i*60}`" fill="none" :stroke="z.zoneId===selected?.zoneId?'#0a9464':'#294953'"/><g v-if="source" tabindex="0" role="button" :aria-label="source.name+'参数'" @click="r.can('PIPE_SAVE',source)&&editPipe(source)" @keydown.enter="r.can('PIPE_SAVE',source)&&editPipe(source)"><rect x="0" y="71" width="140" height="45" rx="7" fill="#e0f8f1" stroke="#8bd9dd"/><text x="70" y="99" text-anchor="middle">♧　{{source.name}}</text></g><g v-if="trunk" tabindex="0" role="button" :aria-label="trunk.name+'参数'" @click="r.can('PIPE_SAVE',trunk)&&editPipe(trunk)" @keydown.enter="r.can('PIPE_SAVE',trunk)&&editPipe(trunk)"><rect x="190" y="69" width="175" height="49" rx="7" fill="#f4f7f8" stroke="#bdcdd3"/><text x="277" y="99" text-anchor="middle">♧　{{trunk.name}}</text></g><g v-for="(z,i) in branches" :key="z.zoneId" tabindex="0" role="button" :aria-label="z.name" @click="select(z)" @keydown.enter="select(z)"><rect x="440" :y="13+i*60" width="163" height="45" rx="7" :fill="z.zoneId===selected?.zoneId?'#e3f7e9':'#f4f7f8'" :stroke="z.zoneId===selected?.zoneId?'#03965e':'#bdcdd3'"/><text x="522" :y="42+i*60" text-anchor="middle">♧　{{z.name}}</text></g></svg></section><section class="panel parameters"><h3 class="panel-title"><button class="btn-plain" :disabled="!selected||!r.can('ZONE_UPDATE',selected)" title="编辑选中分区参数" @click="editZone(selected)">分区参数</button></h3><div v-if="selected" class="parameter-columns"><dl class="data-pairs"><dt>分区编号</dt><dd>{{selected.zoneId}}</dd><dt>分区名称</dt><dd>{{selected.name}}</dd><dt>所属田块</dt><dd>{{fieldName(selected.fieldId)}}</dd><dt>面积（亩）</dt><dd>{{selected.areaMu.toFixed(1)}}</dd><dt>设计流量（m³/h）</dt><dd>{{selected.designFlowM3h}}</dd></dl><dl class="data-pairs"><dt>实测埋深（cm）</dt><dd>{{node?.depthCm??'—'}}</dd><dt>管带间距（cm）</dt><dd>{{node?.intervalCm??'—'}}</dd><dt>供水能力（m³/h）</dt><dd>{{node?.capacityM3h??'—'}}</dd><dt>最多同时运行分区数</dt><dd>{{node?.maxConcurrentZones??'—'}}</dd><dt>计量方式</dt><dd>{{accountingNames[selected.accountingMethod]}}</dd></dl></div><p v-else class="empty-state">暂无分区</p></section></div><section class="panel zone-table"><DataTable :columns="columns" :rows="rows" row-key="zoneId" :selected-id="selected?.zoneId" v-model:sort="ui.sort" @row-click="select"><template #cell-index="{index}">{{(ui.page-1)*15+index+1}}</template><template #cell-fieldId="{value}">{{fieldName(value)}}</template><template #cell-areaMu="{value}">{{value.toFixed(1)}}</template><template #cell-designFlowM3h="{value}">{{value.toFixed(1)}}</template><template #cell-accountingMethod="{value}">{{accountingNames[value]}}</template></DataTable><Pagination v-model="ui.page" :total="zones.length"/></section><ResourceForm v-if="editing" :key="editing.record.zoneId??editing.record.nodeId??editing.action" v-bind="editing" @close="editing=null" @saved="result=>{if(result.entityId?.startsWith('ZON'))ui.selectedId=result.entityId}"/></div></template>
<style scoped>.network-toolbar .filter-field{flex:none;width:206px}.network-toolbar{gap:14px}.network-top{display:grid;grid-template-columns:1.07fr 1fr;gap:10px}.network-top .panel{height:250px;padding:14px 20px}.topology svg{width:100%;height:185px;overflow:visible}.topology svg g{cursor:pointer}.topology text{font-size:16px;fill:#173c40}.parameter-columns{display:grid;grid-template-columns:1fr 1fr;gap:26px}.parameter-columns dl+dl{border-left:1px solid #cbdce0;padding-left:28px}.parameters .data-pairs{gap:13px 10px;font-size:14px;grid-template-columns:auto 1fr}.parameters dd{font-weight:600;white-space:nowrap}.parameters dt{white-space:nowrap}.zone-table{padding:7px 9px 20px}.zone-table :deep(.data-table td){height:30px;padding-top:3px;padding-bottom:3px}.zone-table :deep(.pagination){justify-content:flex-end;padding-right:4px;margin-top:22px}@media(max-width:1200px){.network-top{grid-template-columns:1fr}.network-top .panel{height:auto}}
</style>
